write({"content": "{
  "target_evidence_id": "E2",
  "problem_statement": "agent-command.ts 调用 updateSessionStoreAfterAgentRun 时，将已被覆盖的 provider/model 作为 defaultProvider/defaultModel 传入，导致 session-store.ts 内部 fallback 计算逻辑基于错误基准，无法区分'真实默认值'与'本次运行实际值'，进而可能错误设置 runtime model 和成本估算。",
  "minimal_scope": [
    {"file":"session-store.ts","planned_change":"将入参 defaultProvider/defaultModel 重命名为 actualProvider/actualModel（或 runProvider/runModel），并在函数内部用 fallbackProvider/fallbackModel 作为 fallback 基准；若 fallback 未提供则回退到 actual。修正语义：actual 表示本次运行实际使用的模型，fallback 表示降级候选。"},
    {"file":"agent-command.ts","planned_change":"调整调用 updateSessionStoreAfterAgentRun 时的参数命名映射：传入当前运行实际解析后的 provider/model 作为 actualProvider/actualModel，同时传入原始默认配置中的 defaultProvider/defaultModel 作为 fallbackProvider/fallbackModel（当前逻辑已传 fallbackProvider/fallbackModel，只需调整第一个参数对的真实语义）。"}
  ],
  "invariants": [
    "session-store.ts 函数签名变更仅涉及参数重命名，不改变调用方传入值的顺序和类型",
    "agent-command.ts 中 provider/model 的解析逻辑（覆盖、allowlist、fallback）保持完全不变",
    "updateSessionStoreAfterAgentRun 内部对 modelUsed/providerUsed 的 fallback 链计算结果在改造前后等价"
  ],
  "rollback": [
    "若参数重命名导致其他调用点编译失败，回退为新增可选参数并标记旧参数 @deprecated",
    "若语义调整引发 session entry 中 runtime model 或成本字段异常，立即恢复原始参数名并改为代码注释澄清语义"
  ]
}
", "path": "/app/minimal-redesign-E2.json"})

